from typing import Tuple, List
import bisect
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Bounded lossless optimizer for character-level serialized-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Convert one scalar to evaluator text, mapping scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute an exact LCP using logarithmic C-level slice comparisons."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse from sorted adjacent serialized strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(
            cls._lcp(ordered[i - 1], ordered[i])
            for i in range(1, len(ordered))
        )

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize every source row according to its row-specific permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    def _global_order(self, cells, mode: int) -> List[int]:
        """Rank columns by length-weighted repeated-value savings with deterministic ties."""
        n, m = cells.shape
        ranked = []

        for column in range(m):
            counts = {}
            total_length = 0

            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
                total_length += len(value)

            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repetition = sum(
                count * (count - 1)
                for count in counts.values()
            )

            if mode == 0:
                score = weighted
            else:
                score = weighted + repetition * max(
                    1, total_length // max(1, n)
                )

            ranked.append((score, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    @staticmethod
    def _blocks(m: int, col_merge) -> List[List[int]]:
        """Construct deterministic indivisible column blocks from merge constraints."""
        parent = list(range(m))

        def find(value):
            while parent[value] != value:
                parent[value] = parent[parent[value]]
                value = parent[value]
            return value

        def union(left, right):
            left = find(left)
            right = find(right)
            if left != right:
                parent[right] = left

        for item in (col_merge or []):
            if not isinstance(item, (list, tuple, set, np.ndarray)):
                continue

            values = list(item)
            if len(values) < 2:
                continue

            first = values[0]
            if not isinstance(first, (int, np.integer)):
                continue

            for other in values[1:]:
                if (
                    isinstance(other, (int, np.integer))
                    and 0 <= int(first) < m
                    and 0 <= int(other) < m
                ):
                    union(int(first), int(other))

        groups = {}
        for column in range(m):
            groups.setdefault(find(column), []).append(column)

        return sorted(
            [sorted(block) for block in groups.values()],
            key=lambda block: block[0],
        )

    @staticmethod
    def _move_block(order, block, position) -> List[int]:
        """Move one indivisible block while preserving all other column order."""
        members = set(block)
        remainder = [column for column in order if column not in members]
        position = max(0, min(position, len(remainder)))
        return remainder[:position] + list(block) + remainder[position:]

    @classmethod
    def _row_gain(cls, left, middle, right) -> int:
        """Return the exact sorted-Trie contribution of a string between two neighbors."""
        result = 0
        if left is not None:
            result += cls._lcp(left, middle)
        if right is not None:
            result += cls._lcp(middle, right)
        if left is not None and right is not None:
            result -= cls._lcp(left, right)
        return result

    def _coordinate_refine(self, cells, orders, col_merge):
        """Apply one bounded exact best-response sweep to the longest serialized rows."""
        n, m = cells.shape
        if n < 2 or m < 2:
            return orders

        strings = self._make_strings(cells, orders)
        selected = sorted(
            range(n),
            key=lambda row: (-len(strings[row]), row),
        )[:min(384, n)]

        blocks = self._blocks(m, col_merge)
        block_of = {}
        for block in blocks:
            for column in block:
                block_of[column] = block

        entries = sorted((strings[row], row) for row in range(n))

        for row in selected:
            old_string = strings[row]
            location = bisect.bisect_left(entries, (old_string, row))

            while (
                location < len(entries)
                and entries[location] != (old_string, row)
            ):
                location += 1

            if location >= len(entries):
                continue

            left = entries[location - 1][0] if location else None
            right = (
                entries[location + 1][0]
                if location + 1 < len(entries)
                else None
            )
            old_gain = self._row_gain(left, old_string, right)

            remaining = entries[:location] + entries[location + 1:]
            current = list(orders[row])
            first_block = block_of[current[0]]

            proposals = []
            seen = set()

            # Front moves are the primary row-wise leading-field proposals.
            for column in current[:min(24, m)]:
                block = block_of[column]
                key = tuple(block)
                if key not in seen:
                    seen.add(key)
                    proposals.append(self._move_block(current, block, 0))

            # Position-one moves target useful partial-prefix relationships.
            if len(current) > 1:
                first_text = cells[row, current[0]]

                for column in current[:min(24, m)]:
                    block = block_of[column]
                    if block == first_block:
                        continue

                    block_text = cells[row, block[0]]
                    if (
                        first_text[:8] == block_text[:8]
                        or len(block_text) > len(first_text)
                    ):
                        proposal = self._move_block(current, block, 1)
                        key = tuple(proposal)
                        if key not in seen:
                            seen.add(key)
                            proposals.append(proposal)

            best_gain = old_gain
            best_order = current
            best_string = old_string

            for proposal in proposals:
                candidate = "".join(
                    cells[row, column] for column in proposal
                )
                insertion = bisect.bisect_left(
                    remaining, (candidate, row)
                )

                before = (
                    remaining[insertion - 1][0]
                    if insertion
                    else None
                )
                after = (
                    remaining[insertion][0]
                    if insertion < len(remaining)
                    else None
                )

                gain = self._row_gain(before, candidate, after)

                if gain > best_gain:
                    best_gain = gain
                    best_order = proposal
                    best_string = candidate

            if best_gain > old_gain:
                orders[row] = best_order
                strings[row] = best_string
                entries = remaining
                bisect.insort(entries, (best_string, row))

        return orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select the best global candidate, then perform bounded exact row refinement."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        global_a = self._global_order(cells, 0)
        global_b = self._global_order(cells, 1)

        orders_a = [global_a[:] for _ in range(n)]
        orders_b = [global_b[:] for _ in range(n)]

        score_a = self._trie_score(self._make_strings(cells, orders_a))
        score_b = self._trie_score(self._make_strings(cells, orders_b))

        orders = orders_b if score_b > score_a else orders_a
        orders = self._coordinate_refine(cells, orders, col_merge)

        strings = self._make_strings(cells, orders)
        row_order = sorted(
            range(n),
            key=lambda row: (strings[row], row),
        )

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            permutation = orders[source]
            output[destination, :] = [
                raw[source, column] for column in permutation
            ]
            column_orders.append([
                df.columns[column] for column in permutation
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders

